import os
import subprocess
import json
import re
import zipfile

directory = "/root/papers/all"
results = {}

def get_pdf_content(file_path):
    try:
        result = subprocess.run(['pdftotext', '-f', '1', '-l', '1', file_path, '-'], 
                                capture_output=True, text=True, timeout=10)
        return result.stdout[:2000]
    except Exception as e:
        return f"Error PDF: {str(e)}"

def get_zip_xml_content(file_path, xml_internal_path):
    try:
        with zipfile.ZipFile(file_path, 'r') as zip_ref:
            with zip_ref.open(xml_internal_path) as xml_file:
                content = xml_file.read().decode('utf-8')
                text = re.sub('<[^>]+>', ' ', content)
                return text[:2000]
    except Exception as e:
        return f"Error ZIP: {str(e)}"

for filename in os.listdir(directory):
    file_path = os.path.join(directory, filename)
    if filename.endswith(".pdf"):
        content = get_pdf_content(file_path)
    elif filename.endswith(".docx"):
        content = get_zip_xml_content(file_path, 'word/document.xml')
    elif filename.endswith(".pptx"):
        # Try a few slides or the first one
        content = get_zip_xml_content(file_path, 'ppt/slides/slide1.xml')
    else:
        continue

    results[filename] = content

with open("file_contents.json", "w") as f:
    json.dump(results, f, indent=4)

